// A straight walk down both sides. It emits a remove and an add whenever the
// two lines differ, then moves on.
export function diffLines(a, b) {
  const script = [];
  let i = 0;
  let j = 0;
  while (i < a.length && j < b.length) {
    if (a[i] === b[j]) {
      script.push({ type: 'keep', value: a[i] });
      i += 1;
      j += 1;
      continue;
    }
    script.push({ type: 'remove', value: a[i] });
    script.push({ type: 'add', value: b[j] });
    i += 1;
    j += 1;
  }
  while (i < a.length) {
    script.push({ type: 'remove', value: a[i] });
    i += 1;
  }
  while (j < b.length) {
    script.push({ type: 'add', value: b[j] });
    j += 1;
  }
  return script;
}
